        let rect = egui::Rect::from_min_size(egui::pos2(10.0, 20.0), egui::vec2(0.0, 0.0));
        let (nx, ny) = LuminaApp::to_normalized(egui::pos2(10.0, 20.0), rect, None, (100, 100));
