    #[test]
    fn idle_queue_is_bounded_prioritized_and_cancellable() {
        let mut queue = IdleQueue::new(2);
        let low = queue
            .enqueue(
                IdleTask::MaskInference {
                    mask_id: "low".into(),
                },
                1,
            )
            .unwrap();
        queue
            .enqueue(
                IdleTask::MaskInference {
                    mask_id: "high".into(),
                },
                9,
            )
            .unwrap();
        assert!(queue
            .enqueue(
                IdleTask::MaskInference {
                    mask_id: "full".into()
                },
                9
            )
            .is_none());
        assert!(queue.cancel(low));
        assert_eq!(
            queue.pop_next().unwrap().1,
            IdleTask::MaskInference {
                mask_id: "high".into()
            }
        );
        assert!(queue.is_empty());
    }

